### Create a ChatKit session
# @name CreateChatSessionMethod
POST {{host}}/chatkit/sessions
Authorization: Bearer {{token}}
Content-Type: application/json
Accept: application/json

{
  "workflow": {
    "id": "string",
    "version": "string",
    "state_variables": {},
    "tracing": {
      "enabled": true
    }
  },
  "user": "string",
  "expires_after": {
    "anchor": "created_at",
    "seconds": 0
  },
  "rate_limits": {
    "max_requests_per_1_minute": 0
  },
  "chatkit_configuration": {
    "automatic_thread_titling": {
      "enabled": true
    },
    "file_upload": {
      "enabled": true,
      "max_file_size": 0,
      "max_files": 0
    },
    "history": {
      "enabled": true,
      "recent_threads": 0
    }
  }
}

## Responses
# 200
# Description: Success
# Content-Type: application/json
# 400
# Description: The request is invalid or the required ChatKit beta header is missing or invalid.
# Content-Type: application/json
# 404
# Description: The requested workflow or workflow version was not found or is not accessible.
# Content-Type: application/json
# 429
# Description: The request rate limit has been exceeded.
# Content-Type: application/json

### Create session
# @name create-live
POST {{host}}/live/sessions
Authorization: Bearer {{token}}
Content-Type: application/json
Accept: application/json, text/plain

{
  "session": {
    "model": "gpt-live-1",
    "instructions": "string",
    "audio": {
      "output": {}
    },
    "delegation": {
      "type": "client"
    },
    "store": true,
    "input": [
      {}
    ],
    "client": {
      "data_channel": {}
    }
  },
  "transport": {
    "type": "webrtc",
    "sdp": "string"
  }
}

## Responses
# 201
# Description: Returns 201 Created with a WebRTC answer or an initialized outbound SIP session. A SIP response does not mean the callee has answered.
# Content-Type: application/json
# 400
# Description: Invalid Live session request.
# Content-Type: application/json, text/plain
# 413
# Description: The Live session request exceeds the supported size limit.
# Content-Type: application/json, text/plain
# 429
# Description: The session could not start because a rate or quota limit was exceeded.
# Content-Type: application/json
# 500
# Description: An internal error occurred. The response body is plain text.
# Content-Type: text/plain
# 502
# Description: The SIP gateway could not initialize the outbound call.
# Content-Type: text/plain
# 503
# Description: The session is temporarily unavailable.
# Content-Type: application/json, text/plain
# 504
# Description: SIP session initialization timed out. The error code is sip_setup_timeout.
# Content-Type: application/json

